import 'dart:async';import 'dart:convert';import 'package:http/http.dart' as http;import '../../../core/config/app_environment.dart';import '../../../core/errors/app_exception.dart';
class CreditCardSummary{const CreditCardSummary({required this.accountId,required this.name,required this.institution,required this.limit,required this.balance,required this.outstanding,required this.available,required this.overLimit,required this.utilization,required this.statementDay,required this.dueDay,required this.nextDue});final int accountId;final String name;final String? institution;final double limit,balance,outstanding,available,overLimit,utilization;final int statementDay,dueDay;final DateTime nextDue;factory CreditCardSummary.fromJson(Map<String,dynamic> j)=>CreditCardSummary(accountId:(j['account_id'] as num).toInt(),name:j['name']?.toString()??'',institution:j['institution_name']?.toString(),limit:(j['credit_limit'] as num).toDouble(),balance:(j['current_balance'] as num).toDouble(),outstanding:(j['outstanding_balance'] as num).toDouble(),available:(j['available_credit'] as num).toDouble(),overLimit:(j['over_limit_amount'] as num).toDouble(),utilization:(j['utilization_percent'] as num).toDouble(),statementDay:(j['statement_day'] as num).toInt(),dueDay:(j['payment_due_day'] as num).toInt(),nextDue:DateTime.parse(j['next_payment_due_date'].toString()));}
class CreditApi{CreditApi({required this.config,http.Client? client}):_client=client??http.Client();final AppEnvironmentConfig config;final http.Client _client;static const timeout=Duration(seconds:15);Map<String,String> h(String t)=>{'Accept':'application/json','Authorization':'Bearer '+t};Uri u(String p){final b=Uri.parse(config.apiBaseUrl);return b.replace(path:b.path+p);}Future<http.Response> r(Future<http.Response> Function() f)async{try{return await f().timeout(timeout);}on TimeoutException{throw const NetworkException('The server took too long to respond.');}catch(e){if(e is AppException)rethrow;throw const NetworkException('Unable to reach the server.');}}dynamic d(http.Response x){dynamic v;try{v=jsonDecode(x.body);}catch(_){throw ApiException('Invalid server response.',statusCode:x.statusCode);}if(x.statusCode<200||x.statusCode>=300)throw ApiException(v is Map?v['detail']?.toString()??'Credit request failed.':'Credit request failed.',statusCode:x.statusCode);return v;}Future<List<CreditCardSummary>> list(String t)async{final x=await r(()=>_client.get(u('/api/v1/credit-cards'),headers:h(t)));return (d(x) as List).map((v)=>CreditCardSummary.fromJson(Map<String,dynamic>.from(v as Map))).toList();}Future<CreditCardSummary> configure(String t,int id,{required double limit,required int statementDay,required int dueDay})async{final x=await r(()=>_client.put(u('/api/v1/credit-cards/'+id.toString()),headers:{...h(t),'Content-Type':'application/json'},body:jsonEncode({'credit_limit':limit,'statement_day':statementDay,'payment_due_day':dueDay})));return CreditCardSummary.fromJson(Map<String,dynamic>.from(d(x) as Map));}}